using Test, GravitationalWaveforms, StaticArrays, LinearAlgebra, DelimitedFiles

# SEOBNRv5PHM quasi-precessing EOB dynamics (milestone P2) against pyseobnr 0.3.7 (reference data in
# test/data/phm_dyn, generated by scripts/pyseobnr_phm_dyn_reference.py):
#   - the generated v5PHM Hamiltonian (all seven methods) at random phase-space points;
#   - the circular initial conditions with pyseobnr's own spins (isolates the EOB algebra from the PN-spline floor);
#   - the postadiabatic nodes (grid size, r, pr, pphi, t, phi, omega);
#   - the ODE continuation to merger (phase along pyseobnr's trajectory, end time).
# The ODE reference is pyseobnr's converged result (rtol = atol = 1e-11): at its production 1e-8, with the spins
# updated once per accepted step, its merger phase is 1e-3 .. 1.5e-2 rad from that; our plunge (spins at every RK4
# stage) agrees with the converged result to <= 1.1e-3 rad. q1_c (q = 1) is evaluated at
# m1 = 0.5 + 1e-8: at exactly q = 1 pyseobnr switches to its equal-mass odd-m flux branch (finite `c0` prefixes,
# the q -> 1 limit of the generic formulas), which the SEOBNRv5 flux port does not have (its odd-m flux vanishes at
# exactly q = 1; known open item shared with the aligned-spin models).

const _PHMG = GravitationalWaveforms
const _PHM_DYN_DIR = joinpath(@__DIR__, "data", "phm_dyn")

function _phm_header(f)
    d = Dict{String,Any}()
    for m in eachmatch(r"(\w+)=(\[[^\]]*\]|[-0-9.eE+]+)", readline(f))
        d[m[1]] = m[2][1] == '[' ? parse.(Float64, split(m[2][2:end-1], ",")) : parse(Float64, m[2])
    end
    return d
end
_phm_rows(f) = readdlm(f, ',', Float64; comments = true)

@testset "SEOBNRv5PHM Hamiltonian vs pyseobnr (Ham_AvgS2precess_simple_cython_PA_AD)" begin
    d = _phm_rows(joinpath(_PHM_DYN_DIR, "pyseobnr037_phmham.csv"))
    lens = (9, 4, 6, 1, 9, 1, 16)
    # grad / dynamics / auxderivs 5e-10: the generated derivatives (gen/symbolic) round differently from pyseobnr's CSE
    # trees, and the worst entries are near-circular cancellations at r ~ 25 where pyseobnr's own values carry the
    # error (against a BigFloat evaluation: dH/dr ~ 1e-5, ours 5e-12 vs pyseobnr 1.5e-11; dHeven/dr ~ 5e-7,
    # ours 1.3e-11 vs pyseobnr 2.3e-10)
    tols = (1e-13, 5e-10, 5e-10, 1e-13, 5e-10, 1e-13, 1e-9)
    worst = zeros(7)
    for row in eachrow(d)
        a = Tuple(row[1:19])
        outs = (_PHMG._seobv5phm_ham_call(a...), _PHMG._seobv5phm_ham_grad(a...), _PHMG._seobv5phm_ham_dynamics(a...),
                _PHMG._seobv5phm_ham_omega(a...), _PHMG._seobv5phm_ham_auxderivs(a...), _PHMG._seobv5phm_ham_csi(a...),
                _PHMG._seobv5phm_ham_hessian(a...))
        k = 20
        for j in 1:7
            ref = row[k:k+lens[j]-1]
            k += lens[j]
            v = collect(outs[j])
            # relative to the entry, or to the largest entry of the group for entries that vanish identically
            sc = max.(abs.(ref), 1e-12 * maximum(abs.(ref)))
            worst[j] = max(worst[j], maximum(abs.(v .- ref) ./ sc))
        end
    end
    for j in 1:7
        @test worst[j] < tols[j]
    end
end

const _PHM_TAGS = ("q1.5_a", "q3_b", "q1_c", "q8_d", "q2_e", "q4_f")

@testset "SEOBNRv5PHM dynamics vs pyseobnr ($tag)" for tag in _PHM_TAGS
    icf = joinpath(_PHM_DYN_DIR, "pyseobnr037_phmdyn_$(tag)_ic.csv")
    h = _phm_header(icf)
    m1, m2 = h["m1"], h["m2"]
    if m1 == m2
        m1, m2 = m1 + 1e-8, m2 - 1e-8
    end
    ic = vec(_phm_rows(icf))
    b = _PHMG._seobv5phm_base(m1, m2, h["chi1"], h["chi2"], h["omega_ref"], h["omega_start"])

    # initial conditions with pyseobnr's spins at omega_start
    sp = ic[4:13]
    nu = b.nu
    ap = b.X1 * sp[1] + b.X2 * sp[2]
    am = b.X1 * sp[1] - b.X2 * sp[2]
    chiS = (sp[1] + sp[2]) / 2
    chiA = (sp[1] - sp[2]) / 2
    fc = _PHMG._seobv5_flux_coeffs(nu, b.delta, chiS, chiA, (1 - 2nu) * chiS + b.delta * chiA, b.absN...)
    s = (c1 = SVector(sp[5], sp[6], sp[7]), c2 = SVector(sp[8], sp[9], sp[10]), chi1LN = sp[1], chi2LN = sp[2],
        chi1L = sp[3], chi2L = sp[4], LNhat = SVector(0.0, 0.0, 1.0), ap = ap, am = am,
        dSO = _PHMG._seobv5_dSO(nu, ap, am), fc = fc)
    r0, j0, p0 = _PHMG._seobv5phm_ic(b, s, h["omega_start"])
    tol_ic = m1 == h["m1"] ? 1e-12 : 1e-8      # q1_c is evaluated 1e-8 off q = 1 (see the header)
    @test abs(r0 / ic[1] - 1) < tol_ic
    @test abs(j0 / ic[2] - 1) < tol_ic
    @test abs(p0 / ic[3] - 1) < 1e-6

    # our spins at omega_start (P1 table) vs pyseobnr's spline
    so = _PHMG._seobv5phm_spins(b, h["omega_start"])
    @test maximum(abs.((so.chi1LN - sp[1], so.chi2LN - sp[2], so.chi1L - sp[3], so.chi2L - sp[4]))) < 1e-5

    dyn = seobnrv5phm_dynamics(m1, m2, h["chi1"], h["chi2"], h["omega_ref"], h["omega_start"])
    pa = _phm_rows(joinpath(_PHM_DYN_DIR, "pyseobnr037_phmdyn_$(tag)_pa.csv"))
    @test dyn.pa_success
    @test dyn.npa == size(pa, 1)
    npa = dyn.npa
    if npa == size(pa, 1)
        @test maximum(abs.(dyn.r[1:npa] .- pa[:, 2])) < 1e-5
        @test maximum(abs.(dyn.pr[1:npa] .- pa[:, 4])) < 1e-3 * maximum(abs.(pa[:, 4]))
        @test maximum(abs.(dyn.pphi[1:npa] .- pa[:, 5])) < 1e-5
        @test maximum(abs.(dyn.t[1:npa] .- pa[:, 1])) < 0.05
        @test maximum(abs.(dyn.phi[1:npa] .- pa[:, 3])) < 1e-3
        @test maximum(abs.(dyn.dphi[1:npa] .- pa[:, 11])) < 1e-6
    end

    # ODE: phase along pyseobnr's trajectory (Hermite dense output of our nodes), end time
    ode = _phm_rows(joinpath(_PHM_DYN_DIR, "pyseobnr037_phmdyn_$(tag)_ode.csv"))
    n = dyn.n
    tend = min(dyn.t[n], ode[end, 1]) - 1.0
    worst_phi = 0.0
    worst_r = 0.0
    for k in 1:size(ode, 1)
        tq = ode[k, 1]
        tq > tend && continue
        i = clamp(searchsortedlast(view(dyn.t, 1:n), tq), 1, n - 1)
        hh = dyn.t[i+1] - dyn.t[i]
        x = (tq - dyn.t[i]) / hh
        herm(y, dy) = (2x^3 - 3x^2 + 1) * y[i] + (x^3 - 2x^2 + x) * hh * dy[i] + (-2x^3 + 3x^2) * y[i+1] +
                      (x^3 - x^2) * hh * dy[i+1]
        worst_phi = max(worst_phi, abs(herm(dyn.phi, dyn.dphi) - ode[k, 3]))
        worst_r = max(worst_r, abs(herm(dyn.r, dyn.dr) - ode[k, 2]))
    end
    @test worst_phi < 3e-3
    @test worst_r < 5e-3
    @test abs(dyn.t[n] - ode[end, 1]) < 0.5
    @test dyn.stop in (1, 3)
end

@testset "SEOBNRv5PHM not-a-knot spline helpers" begin
    # exact for cubics: slopes and integrals of y = 2 - x + 3x^2 - 0.5x^3 on a decreasing uniform grid
    n = 12
    x = [10.0 - 0.35 * (i - 1) for i in 1:n]
    f(x) = 2 - x + 3x^2 - 0.5x^3
    df(x) = -1 + 6x - 1.5x^2
    F(x) = 2x - x^2 / 2 + x^3 - x^4 / 8
    y = f.(x)
    s = zeros(n); w = zeros(n); I = zeros(n)
    _PHMG._seobv5phm_spline_slopes!(s, y, x[2] - x[1], n, w)
    _PHMG._seobv5phm_spline_cumint!(I, y, s, x[2] - x[1], n)
    @test maximum(abs.(s .- df.(x))) < 1e-10
    @test maximum(abs.(I .- (F.(x) .- F(x[1])))) < 1e-9
end
